//!43f100's byte counters; geometry and mutation are separate world callbacks.
pub fn advance_frame(base:u16,frame:&mut u8)->bool{if [557,5848,5854].contains(&base){*frame=frame.wrapping_add(1);if *frame!=6{return false;}*frame=0;true}else{*frame=frame.wrapping_add(1)&3;*frame==0}}
pub fn finish_pulse(lifetime:&mut i8)->bool{if *lifetime==127{return false;}*lifetime=lifetime.wrapping_sub(8);*lifetime<0}
